import React from 'react';

export default function PreferencesStep({ data, onChange, onBack }) {
  return (
    <div className="step-card">
      <h3 id="step-title">Preferences</h3>
      <label>Preferred Mode:</label>
      <select 
        id="theme-select"
        value={data.theme}
        onChange={e => onChange({ ...data, theme: e.target.value })}
      >
        <option value="Light Mode">Light Mode</option>
        <option value="Dark Mode">Dark Mode</option>
      </select>
      <button id="back-btn" className="btn-secondary" onClick={onBack}>
        ← Back
      </button>
    </div>
  );
}

