.wizard-app {
  max-width: 460px;
  margin: 0 auto;
  font-family: Inter, sans-serif;
  color: #0f172a;
}
.tab-strip {
  display: flex;
  gap: 8px;
  border-bottom: 2px solid #e2e8f0;
  padding-bottom: 8px;
  margin-bottom: 16px;
}
.tab-pill {
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  padding: 6px 12px;
  border-radius: 6px;
  font-size: 12.5px;
  font-weight: 600;
  color: #475569;
}
.tab-pill.active {
  background: #2563eb;
  color: #ffffff;
  border-color: #1d4ed8;
}
.step-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.step-card h3 {
  margin: 0;
  font-size: 17px;
}

